import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:council/src/services/database_service.dart';
import 'package:council/src/services/search/hybrid_ranker.dart';
import 'package:council/src/services/search/wordpiece_tokenizer.dart';

/// The stages of `shared/golden/search/search.json` that need no native code,
/// checked in the ordinary `flutter test` run.
///
/// The fixture is generated by `integration_test/search_golden_test.dart`,
/// which needs macOS, the ONNX model and the real corpus, so CI on Linux never
/// runs it. These are the pure-Dart stages of the same records: tokenizer ids,
/// the FTS5 match expression, the extracted tag slugs, and reciprocal-rank
/// fusion of the recorded input rankings. A change to any of them that is not
/// reflected in the fixture fails here, before the Swift port inherits it.
void main() {
  TestWidgetsFlutterBinding.ensureInitialized();

  final golden = jsonDecode(
    File('shared/golden/search/search.json').readAsStringSync(),
  ) as Map<String, dynamic>;
  final queries = (golden['queries'] as List).cast<Map<String, dynamic>>();
  final parameters = golden['parameters'] as Map<String, dynamic>;

  late WordPieceTokenizer tokenizer;
  setUpAll(() async => tokenizer = await WordPieceTokenizer.load());

  test('fixture was generated against this corpus and model', () {
    expect(golden['corpusVersion'], DatabaseService.corpusVersion,
        reason: 'the corpus changed; regenerate with tools/search_goldens.sh '
            '--update');
    expect(golden['idSpace'], DatabaseService.idSpace);
    expect(golden['embeddingModel'], DatabaseService.embeddingModel);
    expect(parameters['rrfK'], HybridRanker.k);
    expect(parameters['maxTokens'], WordPieceTokenizer.maxTokens);
  });

  test('WordPiece token ids match the fixture', () {
    for (final q in queries) {
      expect(tokenizer.encode(q['query'] as String),
          (q['tokenIds'] as List).cast<int>(),
          reason: 'tokenIds for ${q['id']}');
    }
  });

  test('FTS5 match expressions match the fixture', () {
    for (final q in queries) {
      expect(DatabaseService.ftsMatchQuery(q['query'] as String), q['ftsMatch'],
          reason: 'ftsMatch for ${q['id']}');
    }
  });

  test('extracted tags match the fixture', () {
    final service = DatabaseService();
    for (final q in queries) {
      expect(service.extractTags(q['query'] as String),
          (q['tags'] as List).cast<String>(),
          reason: 'tags for ${q['id']}');
    }
  });

  test('fusing the recorded rankings gives the recorded fused ranking', () {
    for (final q in queries) {
      final rag = q['rag'] as Map<String, dynamic>;
      expect(
        HybridRanker.fuse(
          lexical: (rag['lexical'] as List).cast<int>(),
          semantic: (rag['semantic'] as List).cast<int>(),
          tags: (rag['tagIds'] as List).cast<int>(),
          limit: parameters['fusionLimit'] as int,
        ),
        (rag['fused'] as List).cast<int>(),
        reason: 'fused for ${q['id']}',
      );
    }
  });
}
